#include <stdexcept>
#include <string>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <map>
#include <vector>
struct Answer { bool found; int value; };
Answer majority(const std::vector<int>& values){
 int candidate=0;std::size_t balance=0;
 for(int v:values){
  if(balance==0){candidate=v;balance=1;}
  else if(v==candidate)++balance;
  else --balance;
 }
 if(balance==0)return {false,0};
 // 후보가 남아도 과반이라는 보장은 없으므로 원본에서 다시 셉니다.
 std::size_t count=0;for(int v:values)if(v==candidate)++count;
 return {count>values.size()/2,candidate};
}
// 공백으로 구분된 정수 토큰 전체를 검사합니다. 1+2를 두 수로 받지 않습니다.
bool read_integer_token(long long& value) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t i = (!token.empty() && (token[0] == '+' || token[0] == '-')) ? 1 : 0;
    if (i == token.size()) return false;
    for (; i < token.size(); ++i) if (token[i] < '0' || token[i] > '9') return false;
    try {
        std::size_t consumed = 0;
        value = std::stoll(token, &consumed, 10);
        return consumed == token.size();
    } catch (const std::invalid_argument&) { return false; }
      catch (const std::out_of_range&) { return false; }
}
int main(){
 long long n=0;if(!read_integer_token(n)||n<0||n>100000)return 1;std::vector<int>v;
 for(long long i=0;i<n;++i){long long x=0;if(!read_integer_token(x)||x<std::numeric_limits<int>::min()||x>std::numeric_limits<int>::max())return 1;v.push_back(static_cast<int>(x));}
 std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
 Answer a=majority(v);if(a.found)std::cout<<a.value<<'\n';else std::cout<<"NONE\n";
 return std::cout?0:1;
}
